{
  "application": "report-generation",
  "case_id": "case-chocolate-retail-sales-2023-2024-en",
  "language": "en",
  "report": {
    "type": "sales-report",
    "audience": "management",
    "tone": "professional, data-forward, actionable"
  },
  "brief": {
    "title": "Chocolate Retail Sales Performance Report (2023–2024)",
    "one_liner": "A comprehensive analysis of chocolate retail sales transactions across stores, products, and customer segments for the 2023–2024 period.",
    "goal": "Equip retail management with a clear understanding of sales trends, profitability drivers, discount effectiveness, and customer purchasing behavior to inform strategic decisions for the upcoming fiscal year."
  },
  "required_sections": [
    {
      "section_id": "executive-summary",
      "title": "Executive Summary",
      "objective": "Provide a high-level overview of total revenue, profit, order volume, and key highlights across the two-year period."
    },
    {
      "section_id": "sales-trends",
      "title": "Sales Trends Over Time",
      "objective": "Analyze monthly and quarterly revenue and order volume trends across 2023 and 2024, identifying seasonality and growth patterns."
    },
    {
      "section_id": "product-performance",
      "title": "Product & Category Performance",
      "objective": "Evaluate which product categories, brands, and individual products generate the most revenue and profit, and assess cocoa percentage as a factor."
    },
    {
      "section_id": "store-analysis",
      "title": "Store & Geographic Performance",
      "objective": "Compare sales performance across stores, cities, countries, and store types to identify top-performing and underperforming locations."
    },
    {
      "section_id": "discount-profitability",
      "title": "Discount Impact & Profitability Analysis",
      "objective": "Assess how discount levels affect revenue, profit margins, and order quantities to evaluate promotional effectiveness."
    },
    {
      "section_id": "customer-insights",
      "title": "Customer Behavior & Loyalty Insights",
      "objective": "Examine purchasing patterns by customer demographics (age, gender) and loyalty membership status to identify high-value segments."
    }
  ],
  "kpis": [
    {
      "name": "Total Revenue",
      "description": "Sum of revenue across all transactions for the reporting period."
    },
    {
      "name": "Total Profit",
      "description": "Sum of profit (revenue minus cost) across all transactions."
    },
    {
      "name": "Average Profit Margin",
      "description": "Mean ratio of profit to revenue, expressed as a percentage."
    },
    {
      "name": "Average Order Value",
      "description": "Mean revenue per transaction (order)."
    },
    {
      "name": "Discount Utilization Rate",
      "description": "Percentage of transactions where a non-zero discount was applied."
    }
  ],
  "analysis_dimensions": [
    "order_date",
    "product_id",
    "store_id",
    "customer_id",
    "discount"
  ]
}

