python3 << 'PYSCRIPT'
import pandas as pd
import json

df = pd.read_csv('/app/benchmark/data.csv')
df['order_date'] = pd.to_datetime(df['order_date'])
df['year'] = df['order_date'].dt.year
df['month'] = df['order_date'].dt.month
df['quarter'] = df['order_date'].dt.quarter
df['year_month'] = df['order_date'].dt.to_period('M').astype(str)
df['year_quarter'] = df['year'].astype(str) + '-Q' + df['quarter'].astype(str)
df['profit_margin'] = df['profit'] / df['revenue']

# ---- Compute all data ----

# KPIs
total_revenue = round(df['revenue'].sum(), 2)
total_profit = round(df['profit'].sum(), 2)
avg_profit_margin = round(df['profit_margin'].mean() * 100, 2)
avg_order_value = round(df['revenue'].mean(), 2)
discount_util = round((df['discount'] > 0).mean() * 100, 2)
total_orders = len(df)

# Yearly
yearly = df.groupby('year').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean')
).reset_index()

rev_2023 = round(yearly[yearly['year']==2023]['revenue'].values[0], 2)
rev_2024 = round(yearly[yearly['year']==2024]['revenue'].values[0], 2)
yoy_rev_growth = round((rev_2024 - rev_2023) / rev_2023 * 100, 2)

profit_2023 = round(yearly[yearly['year']==2023]['profit'].values[0], 2)
profit_2024 = round(yearly[yearly['year']==2024]['profit'].values[0], 2)
yoy_profit_growth = round((profit_2024 - profit_2023) / profit_2023 * 100, 2)

orders_2023 = int(yearly[yearly['year']==2023]['orders'].values[0])
orders_2024 = int(yearly[yearly['year']==2024]['orders'].values[0])
yoy_order_growth = round((orders_2024 - orders_2023) / orders_2023 * 100, 2)

# Monthly trends
monthly = df.groupby('year_month').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count')
).reset_index().sort_values('year_month')

monthly_labels = monthly['year_month'].tolist()
monthly_revenue = [round(x, 2) for x in monthly['revenue'].tolist()]
monthly_profit = [round(x, 2) for x in monthly['profit'].tolist()]
monthly_orders = monthly['orders'].tolist()

# Quarterly trends
quarterly = df.groupby('year_quarter').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count')
).reset_index().sort_values('year_quarter')

q_labels = quarterly['year_quarter'].tolist()
q_revenue = [round(x, 2) for x in quarterly['revenue'].tolist()]
q_profit = [round(x, 2) for x in quarterly['profit'].tolist()]

# YoY monthly
yoy_monthly = df.groupby(['year', 'month']).agg(revenue=('revenue', 'sum')).reset_index()
yoy_pivot = yoy_monthly.pivot(index='month', columns='year', values='revenue').reset_index()
yoy_pivot.columns = ['month', 'rev_2023', 'rev_2024']
yoy_pivot['yoy_growth'] = ((yoy_pivot['rev_2024'] - yoy_pivot['rev_2023']) / yoy_pivot['rev_2023'] * 100)
month_names = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
yoy_labels = month_names
yoy_2023 = [round(x, 2) for x in yoy_pivot['rev_2023'].tolist()]
yoy_2024 = [round(x, 2) for x in yoy_pivot['rev_2024'].tolist()]
yoy_growth = [round(x, 2) for x in yoy_pivot['yoy_growth'].tolist()]

# Seasonality
season = df.groupby('month').agg(
    revenue=('revenue', 'sum'),
    orders=('order_id', 'count')
).reset_index()
season_labels = month_names
season_revenue = [round(x, 2) for x in season['revenue'].tolist()]
season_orders = season['orders'].tolist()

# Product performance - Top 20
product_perf = df.groupby('product_id').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean'),
    total_quantity=('quantity', 'sum')
).reset_index().sort_values('revenue', ascending=False)

top20_products = product_perf.head(20)
prod_labels = top20_products['product_id'].tolist()
prod_revenue = [round(x, 2) for x in top20_products['revenue'].tolist()]
prod_profit = [round(x, 2) for x in top20_products['profit'].tolist()]
prod_margin = [round(x * 100, 2) for x in top20_products['avg_margin'].tolist()]

# Bottom 10 products
bottom10_products = product_perf.tail(10)
bottom_prod_labels = bottom10_products['product_id'].tolist()
bottom_prod_revenue = [round(x, 2) for x in bottom10_products['revenue'].tolist()]

# Product revenue distribution
prod_rev_stats = {
    'min': round(product_perf['revenue'].min(), 2),
    'max': round(product_perf['revenue'].max(), 2),
    'mean': round(product_perf['revenue'].mean(), 2),
    'median': round(product_perf['revenue'].median(), 2),
    'std': round(product_perf['revenue'].std(), 2)
}

# Store performance - Top 20
store_perf = df.groupby('store_id').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean')
).reset_index().sort_values('revenue', ascending=False)

top20_stores = store_perf.head(20)
store_labels = top20_stores['store_id'].tolist()
store_revenue = [round(x, 2) for x in top20_stores['revenue'].tolist()]
store_profit = [round(x, 2) for x in top20_stores['profit'].tolist()]
store_margin = [round(x * 100, 2) for x in top20_stores['avg_margin'].tolist()]

# Bottom 10 stores
bottom10_stores = store_perf.tail(10)

store_rev_stats = {
    'min': round(store_perf['revenue'].min(), 2),
    'max': round(store_perf['revenue'].max(), 2),
    'mean': round(store_perf['revenue'].mean(), 2),
    'std': round(store_perf['revenue'].std(), 2)
}

# Discount analysis
df['discount_bin'] = pd.cut(df['discount'], bins=[-0.001, 0.0, 0.05, 0.10, 0.15, 0.20, 1.0],
                            labels=['0%', '1-5%', '6-10%', '11-15%', '16-20%', '20%+'])
discount_analysis = df.groupby('discount_bin', observed=False).agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean'),
    avg_quantity=('quantity', 'mean'),
    avg_revenue_per_order=('revenue', 'mean')
).reset_index()

disc_labels = discount_analysis['discount_bin'].astype(str).tolist()
disc_revenue = [round(x, 2) for x in discount_analysis['revenue'].tolist()]
disc_profit = [round(x, 2) for x in discount_analysis['profit'].tolist()]
disc_orders = discount_analysis['orders'].tolist()
disc_avg_margin = [round(x * 100, 2) if pd.notna(x) else 0 for x in discount_analysis['avg_margin'].tolist()]
disc_avg_qty = [round(x, 2) if pd.notna(x) else 0 for x in discount_analysis['avg_quantity'].tolist()]
disc_avg_rev = [round(x, 2) if pd.notna(x) else 0 for x in discount_analysis['avg_revenue_per_order'].tolist()]

# Discounted vs non-discounted
df['has_discount'] = df['discount'] > 0
disc_comp = df.groupby('has_discount').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean'),
    avg_quantity=('quantity', 'mean'),
    avg_revenue=('revenue', 'mean')
).reset_index()

no_disc_margin = round(disc_comp[disc_comp['has_discount']==False]['avg_margin'].values[0] * 100, 2)
with_disc_margin = round(disc_comp[disc_comp['has_discount']==True]['avg_margin'].values[0] * 100, 2)
no_disc_avg_rev = round(disc_comp[disc_comp['has_discount']==False]['avg_revenue'].values[0], 2)
with_disc_avg_rev = round(disc_comp[disc_comp['has_discount']==True]['avg_revenue'].values[0], 2)
no_disc_avg_qty = round(disc_comp[disc_comp['has_discount']==False]['avg_quantity'].values[0], 2)
with_disc_avg_qty = round(disc_comp[disc_comp['has_discount']==True]['avg_quantity'].values[0], 2)

# Customer segments
customer_stats = df.groupby('customer_id').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean')
).reset_index()

customer_stats['segment'] = pd.cut(customer_stats['orders'], bins=[0, 1, 3, 5, 10, 100],
                                    labels=['One-time (1)', 'Low (2-3)', 'Medium (4-5)', 'High (6-9)', 'VIP (10+)'])
segment_analysis = customer_stats.groupby('segment', observed=False).agg(
    customers=('customer_id', 'count'),
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    avg_orders=('orders', 'mean')
).reset_index()

seg_labels = segment_analysis['segment'].astype(str).tolist()
seg_customers = segment_analysis['customers'].tolist()
seg_revenue = [round(x, 2) for x in segment_analysis['revenue'].tolist()]
seg_profit = [round(x, 2) for x in segment_analysis['profit'].tolist()]

# Customer order frequency distribution
freq = customer_stats['orders'].value_counts().sort_index()
freq_labels = [str(x) for x in freq.index.tolist()]
freq_values = freq.values.tolist()

unique_customers = df['customer_id'].nunique()
repeat_rate = round((customer_stats['orders'] > 1).sum() / len(customer_stats) * 100, 2)
avg_orders_per_customer = round(customer_stats['orders'].mean(), 2)
avg_rev_per_customer = round(customer_stats['revenue'].mean(), 2)

# ---- Build HTML ----
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Chocolate Retail Sales Performance Report (2023–2024)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --primary: #3b1f0b;
    --primary-light: #6b3a1f;
    --accent: #d4a574;
    --accent-light: #e8c9a0;
    --bg: #faf8f5;
    --card-bg: #ffffff;
    --text: #2d2016;
    --text-muted: #7a6b5d;
    --success: #2d7d46;
    --success-bg: #e8f5e9;
    --warning: #c27a14;
    --warning-bg: #fff8e1;
    --danger: #c0392b;
    --danger-bg: #fde8e6;
    --info: #1a6fa0;
    --info-bg: #e3f2fd;
    --border: #e8ddd0;
    --shadow: 0 2px 8px rgba(59,31,11,0.08);
    --shadow-hover: 0 4px 16px rgba(59,31,11,0.12);
  }}

  * {{ margin: 0; padding: 0; box-sizing: border-box; }}

  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 15px;
  }}

  .report-container {{
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
  }}

  /* Header */
  .report-header {{
    background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
    color: #fff;
    padding: 48px 40px;
    border-radius: 12px;
    margin-bottom: 32px;
    position: relative;
    overflow: hidden;
  }}
  .report-header::before {{
    content: '';
    position: absolute;
    top: -50%;
    right: -20%;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(212,165,116,0.15) 0%, transparent 70%);
    border-radius: 50%;
  }}
  .report-header h1 {{
    font-size: 32px;
    font-weight: 700;
    margin-bottom: 8px;
    position: relative;
  }}
  .report-header .subtitle {{
    font-size: 18px;
    opacity: 0.85;
    font-weight: 400;
    position: relative;
  }}
  .report-header .meta {{
    margin-top: 16px;
    font-size: 14px;
    opacity: 0.7;
    position: relative;
  }}

  /* KPI Cards */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 32px;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 24px 20px;
    text-align: center;
    box-shadow: var(--shadow);
    border-top: 4px solid var(--accent);
    transition: box-shadow 0.2s;
  }}
  .kpi-card:hover {{ box-shadow: var(--shadow-hover); }}
  .kpi-card .kpi-label {{
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--text-muted);
    margin-bottom: 8px;
    font-weight: 600;
  }}
  .kpi-card .kpi-value {{
    font-size: 28px;
    font-weight: 700;
    color: var(--primary);
  }}
  .kpi-card .kpi-sub {{
    font-size: 12px;
    color: var(--text-muted);
    margin-top: 4px;
  }}

  /* Sections */
  .section {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 32px;
    margin-bottom: 24px;
    box-shadow: var(--shadow);
  }}
  .section-title {{
    font-size: 22px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 8px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--accent-light);
  }}
  .section-objective {{
    font-size: 14px;
    color: var(--text-muted);
    margin-bottom: 24px;
    font-style: italic;
  }}

  /* Chart containers */
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
  }}
  .chart-row.full {{
    grid-template-columns: 1fr;
  }}
  .chart-box {{
    background: var(--bg);
    border-radius: 8px;
    padding: 20px;
    border: 1px solid var(--border);
  }}
  .chart-box h3 {{
    font-size: 15px;
    font-weight: 600;
    color: var(--primary-light);
    margin-bottom: 12px;
  }}
  .chart-container {{
    position: relative;
    width: 100%;
    height: 320px;
  }}
  .chart-container.tall {{ height: 400px; }}

  /* Callout boxes */
  .callout {{
    padding: 16px 20px;
    border-radius: 8px;
    margin: 16px 0;
    font-size: 14px;
    line-height: 1.6;
  }}
  .callout-insight {{ background: var(--info-bg); border-left: 4px solid var(--info); }}
  .callout-success {{ background: var(--success-bg); border-left: 4px solid var(--success); }}
  .callout-warning {{ background: var(--warning-bg); border-left: 4px solid var(--warning); }}
  .callout-danger {{ background: var(--danger-bg); border-left: 4px solid var(--danger); }}
  .callout strong {{ display: block; margin-bottom: 4px; }}

  /* Tables */
  .data-table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    margin: 16px 0;
  }}
  .data-table th {{
    background: var(--primary);
    color: #fff;
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }}
  .data-table td {{
    padding: 8px 12px;
    border-bottom: 1px solid var(--border);
  }}
  .data-table tr:nth-child(even) {{ background: var(--bg); }}
  .data-table tr:hover {{ background: var(--accent-light); }}
  .data-table .num {{ text-align: right; font-variant-numeric: tabular-nums; }}

  /* Comparison badges */
  .badge {{
    display: inline-block;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 12px;
    font-weight: 600;
  }}
  .badge-up {{ background: var(--success-bg); color: var(--success); }}
  .badge-down {{ background: var(--danger-bg); color: var(--danger); }}
  .badge-neutral {{ background: var(--warning-bg); color: var(--warning); }}

  /* Two-col stat cards */
  .stat-pair {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin: 16px 0;
  }}
  .stat-card {{
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px;
    text-align: center;
  }}
  .stat-card .stat-label {{
    font-size: 13px;
    color: var(--text-muted);
    margin-bottom: 6px;
  }}
  .stat-card .stat-value {{
    font-size: 24px;
    font-weight: 700;
    color: var(--primary);
  }}
  .stat-card .stat-detail {{
    font-size: 12px;
    color: var(--text-muted);
    margin-top: 4px;
  }}

  /* Narrative text */
  .narrative {{
    font-size: 14px;
    line-height: 1.7;
    color: var(--text);
    margin: 12px 0;
  }}
  .narrative strong {{ color: var(--primary); }}

  /* Footer */
  .report-footer {{
    text-align: center;
    padding: 24px;
    color: var(--text-muted);
    font-size: 12px;
    border-top: 1px solid var(--border);
    margin-top: 16px;
  }}

  /* YoY table in exec summary */
  .yoy-grid {{
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin: 16px 0;
  }}
  .yoy-card {{
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
    text-align: center;
  }}
  .yoy-card .yoy-label {{ font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; }}
  .yoy-card .yoy-2023 {{ font-size: 16px; font-weight: 600; color: var(--text-muted); margin-top: 4px; }}
  .yoy-card .yoy-2024 {{ font-size: 22px; font-weight: 700; color: var(--primary); }}
  .yoy-card .yoy-change {{ font-size: 14px; font-weight: 600; margin-top: 4px; }}

  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(3, 1fr); }}
    .chart-row {{ grid-template-columns: 1fr; }}
    .yoy-grid {{ grid-template-columns: 1fr; }}
  }}
  @media (max-width: 600px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .report-header {{ padding: 24px; }}
    .report-header h1 {{ font-size: 22px; }}
    .section {{ padding: 20px; }}
  }}
</style>
</head>
<body>
<div class="report-container">

  <!-- HEADER -->
  <div class="report-header">
    <h1>Chocolate Retail Sales Performance Report</h1>
    <div class="subtitle">Comprehensive Analysis of 2023–2024 Performance</div>
    <div class="meta">Reporting Period: January 2023 – December 2024 &nbsp;|&nbsp; Dataset: 50,000 Transactions &nbsp;|&nbsp; Prepared for Retail Management</div>
  </div>

  <!-- EXECUTIVE SUMMARY -->
  <div class="section" id="executive-summary">
    <h2 class="section-title">Executive Summary</h2>
    <div class="section-objective">High-level overview of total revenue, profit, order volume, and key highlights across the two-year period.</div>

    <!-- KPI Dashboard -->
    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="kpi-label">Total Revenue</div>
        <div class="kpi-value">${total_revenue:,.0f}</div>
        <div class="kpi-sub">${rev_2023:,.0f} (2023) → ${rev_2024:,.0f} (2024)</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Total Profit</div>
        <div class="kpi-value">${total_profit:,.0f}</div>
        <div class="kpi-sub">${profit_2023:,.0f} (2023) → ${profit_2024:,.0f} (2024)</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Profit Margin</div>
        <div class="kpi-value">{avg_profit_margin:.1f}%</div>
        <div class="kpi-sub">Consistent across both years</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Avg Order Value</div>
        <div class="kpi-value">${avg_order_value:.2f}</div>
        <div class="kpi-sub">{total_orders:,} total orders</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Discount Utilization</div>
        <div class="kpi-value">{discount_util:.1f}%</div>
        <div class="kpi-sub">of transactions discounted</div>
      </div>
    </div>

    <!-- YoY Comparison -->
    <div class="yoy-grid">
      <div class="yoy-card">
        <div class="yoy-label">Revenue YoY</div>
        <div class="yoy-2023">${rev_2023:,.0f}</div>
        <div class="yoy-2024">${rev_2024:,.0f}</div>
        <div class="yoy-change"><span class="badge badge-up">+{yoy_rev_growth:.2f}%</span></div>
      </div>
      <div class="yoy-card">
        <div class="yoy-label">Profit YoY</div>
        <div class="yoy-2023">${profit_2023:,.0f}</div>
        <div class="yoy-2024">${profit_2024:,.0f}</div>
        <div class="yoy-change"><span class="badge badge-up">+{yoy_profit_growth:.2f}%</span></div>
      </div>
      <div class="yoy-card">
        <div class="yoy-label">Orders YoY</div>
        <div class="yoy-2023">{orders_2023:,}</div>
        <div class="yoy-2024">{orders_2024:,}</div>
        <div class="yoy-change"><span class="badge badge-up">+{yoy_order_growth:.2f}%</span></div>
      </div>
    </div>

    <div class="callout callout-insight">
      <strong>Key Takeaway</strong>
      The business grew modestly at <strong>+{yoy_rev_growth:.1f}% revenue YoY</strong>, with profit margin holding steady at ~40%. 
      Discounting is used in {discount_util:.0f}% of transactions but does not erode margins significantly, suggesting well-controlled promotional pricing. 
      The primary growth lever remains order volume rather than average order value, which declined slightly under discounting.
    </div>
  </div>

  <!-- SALES TRENDS OVER TIME -->
  <div class="section" id="sales-trends">
    <h2 class="section-title">Sales Trends Over Time</h2>
    <div class="section-objective">Monthly and quarterly revenue and order volume trends across 2023 and 2024, identifying seasonality and growth patterns.</div>

    <div class="chart-row full">
      <div class="chart-box">
        <h3>Monthly Revenue & Profit Trend</h3>
        <div class="chart-container tall">
          <canvas id="monthlyTrendChart"></canvas>
        </div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box">
        <h3>Quarterly Revenue</h3>
        <div class="chart-container">
          <canvas id="quarterlyChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h3>Year-over-Year Monthly Revenue Comparison</h3>
        <div class="chart-container">
          <canvas id="yoyChart"></canvas>
        </div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box">
        <h3>Monthly Order Volume</h3>
        <div class="chart-container">
          <canvas id="monthlyOrdersChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h3>Month-over-Year Revenue Growth (%)</h3>
        <div class="chart-container">
          <canvas id="yoyGrowthChart"></canvas>
        </div>
      </div>
    </div>

    <div class="callout callout-insight">
      <strong>Seasonality & Growth Insights</strong>
      Revenue shows <strong>modest seasonality</strong>: Q1 tends to be slightly softer (January recovery, February dip), while Q3 (July–September) typically delivers the strongest performance. 
      2024 showed a positive revenue shift in the first half (+2.8% to +10.4% YoY in Feb–Jun), but the second half was mixed, with September and December declining (-6.3% and -7.5% respectively). 
      Order volume mirrors revenue patterns closely, indicating that growth is driven primarily by transaction count rather than basket size.
    </div>

    <table class="data-table">
      <thead>
        <tr><th>Quarter</th><th class="num">Revenue</th><th class="num">Profit</th><th class="num">Orders</th></tr>
      </thead>
      <tbody>
        {"".join(f'<tr><td>{r["year_quarter"]}</td><td class="num">${r["revenue"]:,.2f}</td><td class="num">${r["profit"]:,.2f}</td><td class="num">{r["orders"]:,}</td></tr>' for _, r in quarterly.iterrows())}
      </tbody>
    </table>
  </div>

  <!-- PRODUCT & CATEGORY PERFORMANCE -->
  <div class="section" id="product-performance">
    <h2 class="section-title">Product & Category Performance</h2>
    <div class="section-objective">Which products generate the most revenue and profit, and how does product pricing affect performance.</div>

    <div class="stat-pair">
      <div class="stat-card">
        <div class="stat-label">Unique Products</div>
        <div class="stat-value">{df['product_id'].nunique()}</div>
        <div class="stat-detail">Avg Revenue/Product: ${product_perf['revenue'].mean():,.0f}</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Revenue Range</div>
        <div class="stat-value">${prod_rev_stats["min"]:,.0f} – ${prod_rev_stats["max"]:,.0f}</div>
        <div class="stat-detail">Std Dev: ${prod_rev_stats["std"]:,.0f}</div>
      </div>
    </div>

    <div class="chart-row full">
      <div class="chart-box">
        <h3>Top 20 Products by Revenue</h3>
        <div class="chart-container tall">
          <canvas id="topProductsChart"></canvas>
        </div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box">
        <h3>Top 20 Products — Profit Margin (%)</h3>
        <div class="chart-container">
          <canvas id="productMarginChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h3>Revenue Distribution Across All Products</h3>
        <div class="chart-container">
          <canvas id="productDistChart"></canvas>
        </div>
      </div>
    </div>

    <div class="callout callout-insight">
      <strong>Product Performance Insights</strong>
      Product revenue is <strong>remarkably evenly distributed</strong> — the top product (P0168 at ${top20_products.iloc[0]['revenue']:,.0f}) generates only ~1.5× the revenue of the median product. 
      Profit margins are highly consistent across the portfolio (~39–41%), indicating a uniform pricing and costing strategy. 
      Without brand/category dimension data, we cannot assess category-level dynamics; however, the uniform performance suggests product differentiation is low, and growth would likely require portfolio expansion or pricing innovation rather than concentrating on existing winners.
    </div>

    <table class="data-table">
      <thead>
        <tr><th>Product ID</th><th class="num">Revenue</th><th class="num">Profit</th><th class="num">Orders</th><th class="num">Avg Margin</th><th class="num">Total Qty</th></tr>
      </thead>
      <tbody>
        {"".join(f'<tr><td>{r["product_id"]}</td><td class="num">${r["revenue"]:,.2f}</td><td class="num">${r["profit"]:,.2f}</td><td class="num">{r["orders"]:,}</td><td class="num">{r["avg_margin"]*100:.1f}%</td><td class="num">{r["total_quantity"]:,}</td></tr>' for _, r in top20_products.iterrows())}
      </tbody>
    </table>

    <h3 style="margin-top:24px;font-size:16px;color:var(--primary-light);">Bottom 10 Products</h3>
    <table class="data-table">
      <thead>
        <tr><th>Product ID</th><th class="num">Revenue</th><th class="num">Profit</th><th class="num">Orders</th><th class="num">Avg Margin</th></tr>
      </thead>
      <tbody>
        {"".join(f'<tr><td>{r["product_id"]}</td><td class="num">${r["revenue"]:,.2f}</td><td class="num">${r["profit"]:,.2f}</td><td class="num">{r["orders"]:,}</td><td class="num">{r["avg_margin"]*100:.1f}%</td></tr>' for _, r in bottom10_products.iterrows())}
      </tbody>
    </table>
  </div>

  <!-- STORE & GEOGRAPHIC PERFORMANCE -->
  <div class="section" id="store-analysis">
    <h2 class="section-title">Store & Geographic Performance</h2>
    <div class="section-objective">Sales performance across stores to identify top-performing and underperforming locations.</div>

    <div class="stat-pair">
      <div class="stat-card">
        <div class="stat-label">Unique Stores</div>
        <div class="stat-value">{df['store_id'].nunique()}</div>
        <div class="stat-detail">Avg Revenue/Store: ${store_perf['revenue'].mean():,.0f}</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Revenue Range</div>
        <div class="stat-value">${store_rev_stats["min"]:,.0f} – ${store_rev_stats["max"]:,.0f}</div>
        <div class="stat-detail">Std Dev: ${store_rev_stats["std"]:,.0f}</div>
      </div>
    </div>

    <div class="chart-row full">
      <div class="chart-box">
        <h3>Top 20 Stores by Revenue</h3>
        <div class="chart-container tall">
          <canvas id="topStoresChart"></canvas>
        </div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box">
        <h3>Top 20 Stores — Profit Margin (%)</h3>
        <div class="chart-container">
          <canvas id="storeMarginChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h3>Store Revenue Distribution</h3>
        <div class="chart-container">
          <canvas id="storeDistChart"></canvas>
        </div>
      </div>
    </div>

    <div class="callout callout-warning">
      <strong>Store Performance Insights</strong>
      Store revenue follows a <strong>tight distribution</strong> (std dev ${store_rev_stats["std"]:,.0f} around a ${store_rev_stats["mean"]:,.0f} mean), with the top store (S075 at ${top20_stores.iloc[0]['revenue']:,.0f}) outperforming the bottom (S057 at ${store_perf.sort_values('revenue').iloc[0]['revenue']:,.0f}) by only ~30%. 
      Margins are consistent across stores (~39.5–40.9%), indicating standardized operations. Without city/country/store-type dimension data, geographic or format-level analysis cannot be performed. The narrow spread suggests all stores are similarly productive — differentiation may require local assortment or promotional strategies.
    </div>

    <table class="data-table">
      <thead>
        <tr><th>Store ID</th><th class="num">Revenue</th><th class="num">Profit</th><th class="num">Orders</th><th class="num">Avg Margin</th></tr>
      </thead>
      <tbody>
        {"".join(f'<tr><td>{r["store_id"]}</td><td class="num">${r["revenue"]:,.2f}</td><td class="num">${r["profit"]:,.2f}</td><td class="num">{r["orders"]:,}</td><td class="num">{r["avg_margin"]*100:.1f}%</td></tr>' for _, r in top20_stores.iterrows())}
      </tbody>
    </table>

    <h3 style="margin-top:24px;font-size:16px;color:var(--primary-light);">Bottom 10 Stores</h3>
    <table class="data-table">
      <thead>
        <tr><th>Store ID</th><th class="num">Revenue</th><th class="num">Profit</th><th class="num">Orders</th><th class="num">Avg Margin</th></tr>
      </thead>
      <tbody>
        {"".join(f'<tr><td>{r["store_id"]}</td><td class="num">${r["revenue"]:,.2f}</td><td class="num">${r["profit"]:,.2f}</td><td class="num">{r["orders"]:,}</td><td class="num">{r["avg_margin"]*100:.1f}%</td></tr>' for _, r in bottom10_stores.iterrows())}
      </tbody>
    </table>
  </div>

  <!-- DISCOUNT IMPACT & PROFITABILITY -->
  <div class="section" id="discount-profitability">
    <h2 class="section-title">Discount Impact & Profitability Analysis</h2>
    <div class="section-objective">How discount levels affect revenue, profit margins, and order quantities to evaluate promotional effectiveness.</div>

    <div class="stat-pair">
      <div class="stat-card">
        <div class="stat-label">No-Discount Avg Order Value</div>
        <div class="stat-value">${no_disc_avg_rev:.2f}</div>
        <div class="stat-detail">Margin: {no_disc_margin:.1f}% | Avg Qty: {no_disc_avg_qty:.1f}</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Discounted Avg Order Value</div>
        <div class="stat-value">${with_disc_avg_rev:.2f}</div>
        <div class="stat-detail">Margin: {with_disc_margin:.1f}% | Avg Qty: {with_disc_avg_qty:.1f}</div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box">
        <h3>Revenue & Profit by Discount Level</h3>
        <div class="chart-container">
          <canvas id="discountRevChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h3>Avg Profit Margin by Discount Level</h3>
        <div class="chart-container">
          <canvas id="discountMarginChart"></canvas>
        </div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box">
        <h3>Order Count by Discount Level</h3>
        <div class="chart-container">
          <canvas id="discountOrdersChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h3>Avg Revenue per Order by Discount Level</h3>
        <div class="chart-container">
          <canvas id="discountAovChart"></canvas>
        </div>
      </div>
    </div>

    <div class="callout callout-warning">
      <strong>Discount Effectiveness: Margins Hold, But Revenue per Order Drops</strong>
      Discounted transactions show <strong>virtually identical profit margins (~40%)</strong> compared to non-discounted ones, indicating that cost structures adjust proportionally. However, the <strong>average order value declines from ${no_disc_avg_rev:.2f} (no discount) to ${with_disc_avg_rev:.2f} (discounted)</strong>, a {round((no_disc_avg_rev - with_disc_avg_rev) / no_disc_avg_rev * 100, 1):.1f}% reduction. 
      Critically, discounting does <strong>not drive higher quantities</strong> per order ({with_disc_avg_qty:.1f} vs {no_disc_avg_qty:.1f} units), meaning discounts reduce per-transaction revenue without a volume uplift. 
      The three active discount tiers (6–10%, 11–15%, 16–20%) show progressively lower per-order revenue with no margin benefit, suggesting that promotional discounting is a <strong>revenue-neutral to revenue-negative strategy</strong> unless it drives incremental store traffic not captured at the transaction level.
    </div>

    <table class="data-table">
      <thead>
        <tr><th>Discount Level</th><th class="num">Revenue</th><th class="num">Profit</th><th class="num">Orders</th><th class="num">Avg Margin</th><th class="num">Avg Qty</th><th class="num">Avg Order Value</th></tr>
      </thead>
      <tbody>
        {"".join(f'<tr><td>{r["discount_bin"]}</td><td class="num">${r["revenue"]:,.2f}</td><td class="num">${r["profit"]:,.2f}</td><td class="num">{r["orders"]:,}</td><td class="num">{r["avg_margin"]*100:.1f}%</td><td class="num">{r["avg_quantity"]:.1f}</td><td class="num">${r["avg_revenue_per_order"]:.2f}</td></tr>' if r["orders"] > 0 else f'<tr><td>{r["discount_bin"]}</td><td class="num" colspan="6" style="text-align:center;color:var(--text-muted)">No transactions in this range</td></tr>' for _, r in discount_analysis.iterrows())}
      </tbody>
    </table>
  </div>

  <!-- CUSTOMER BEHAVIOR & LOYALTY -->
  <div class="section" id="customer-insights">
    <h2 class="section-title">Customer Behavior & Loyalty Insights</h2>
    <div class="section-objective">Purchasing patterns by customer segments and repeat purchase behavior to identify high-value segments.</div>

    <div class="stat-pair">
      <div class="stat-card">
        <div class="stat-label">Unique Customers</div>
        <div class="stat-value">{unique_customers:,}</div>
        <div class="stat-detail">Avg {avg_orders_per_customer:.2f} orders/customer</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Repeat Purchase Rate</div>
        <div class="stat-value">{repeat_rate:.1f}%</div>
        <div class="stat-detail">Avg Rev/Customer: ${avg_rev_per_customer:.2f}</div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box">
        <h3>Revenue by Customer Segment</h3>
        <div class="chart-container">
          <canvas id="segmentRevChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h3>Customer Count by Segment</h3>
        <div class="chart-container">
          <canvas id="segmentCountChart"></canvas>
        </div>
      </div>
    </div>

    <div class="chart-row">
      <div class="chart-box">
        <h3>Customer Order Frequency Distribution</h3>
        <div class="chart-container">
          <canvas id="freqChart"></canvas>
        </div>
      </div>
      <div class="chart-box">
        <h3>Profit by Customer Segment</h3>
        <div class="chart-container">
          <canvas id="segmentProfitChart"></canvas>
        </div>
      </div>
    </div>

    <div class="callout callout-insight">
      <strong>Customer Behavior Insights</strong>
      The customer base is predominantly <strong>one-time buyers (58.0%)</strong>, with only {repeat_rate:.1f}% making repeat purchases. 
      The <strong>Low-frequency segment (2–3 orders)</strong> contributes the largest revenue share (${segment_analysis[segment_analysis['segment']=='Low (2-3)']['revenue'].values[0]:,.0f}), despite representing ~39% of customers. 
      Medium and High-frequency customers are rare (0.9% combined) but deliver disproportionately higher per-customer revenue. 
      The low repeat rate represents a <strong>significant growth opportunity</strong>: converting even a small portion of one-time buyers into repeat customers could substantially increase lifetime value.
    </div>

    <div class="callout callout-warning">
      <strong>Data Limitation</strong>
      The dataset does not include customer demographic fields (age, gender, loyalty membership) or store geographic attributes (city, country, store type). Analysis of loyalty member vs. non-member purchasing behavior and demographic segmentation cannot be performed with the available data. Enrichment with customer and store dimension tables would enable deeper insight.
    </div>

    <table class="data-table">
      <thead>
        <tr><th>Segment</th><th class="num">Customers</th><th class="num">Revenue</th><th class="num">Profit</th><th class="num">Avg Orders</th></tr>
      </thead>
      <tbody>
        {"".join(f'<tr><td>{r["segment"]}</td><td class="num">{r["customers"]:,}</td><td class="num">${r["revenue"]:,.2f}</td><td class="num">${r["profit"]:,.2f}</td><td class="num">{r["avg_orders"]:.1f}</td></tr>' for _, r in segment_analysis.iterrows())}
      </tbody>
    </table>
  </div>

  <!-- RECOMMENDATIONS -->
  <div class="section" id="recommendations">
    <h2 class="section-title">Strategic Recommendations</h2>
    <div class="section-objective">Actionable recommendations based on the analysis findings.</div>

    <div class="callout callout-success">
      <strong>1. Invest in Customer Retention Programs</strong>
      With 58% of customers being one-time buyers and a repeat rate of only {repeat_rate:.1f}%, loyalty and re-engagement initiatives (e.g., personalized follow-ups, loyalty rewards, win-back campaigns) represent the single largest growth lever. Even a 5-point increase in repeat rate could add significant incremental revenue.
    </div>

    <div class="callout callout-warning">
      <strong>2. Re-evaluate Discount Strategy</strong>
      Discounts reduce average order value by ~16% without increasing quantities per order or improving margins. Consider shifting from blanket percentage discounts to targeted promotions (e.g., bundle deals, minimum-spend thresholds) that protect per-transaction revenue while incentivizing larger baskets.
    </div>

    <div class="callout callout-insight">
      <strong>3. Address Q4 Softening in 2024</strong>
      September and December 2024 saw notable YoY declines (-6.3% and -7.5%). Investigate root causes — competitive pressure, inventory issues, or demand shifts — and develop targeted Q4 2025 campaigns to recover momentum during these historically softer months.
    </div>

    <div class="callout callout-insight">
      <strong>4. Leverage Top Stores as Benchmarks</strong>
      The top-performing stores (S075, S076, S094) generate ~30% more revenue than the bottom. Conduct operational audits to identify replicable practices (staffing, layout, local marketing) that can be transferred to underperforming locations.
    </div>

    <div class="callout callout-warning">
      <strong>5. Enrich Data for Deeper Analysis</strong>
      Critical dimension data (product categories, store geographies, customer demographics, loyalty status) is unavailable in the current dataset. Investing in data integration with the product, store, and customer dimension tables would unlock category-level, geographic, and loyalty-based insights essential for strategic planning.
    </div>
  </div>

  <!-- FOOTER -->
  <div class="report-footer">
    Chocolate Retail Sales Performance Report &nbsp;|&nbsp; Data Source: 50,000 transactions, Jan 2023 – Dec 2024 &nbsp;|&nbsp; Generated for Retail Management
  </div>

</div>

<!-- CHARTS -->
<script>
const PRIMARY = '#3b1f0b';
const PRIMARY_LIGHT = '#6b3a1f';
const ACCENT = '#d4a574';
const ACCENT_LIGHT = '#e8c9a0';
const MUTED = '#7a6b5d';
const SUCCESS = '#2d7d46';
const WARNING = '#c27a14';

Chart.defaults.font.family = "'Segoe UI', -apple-system, sans-serif";
Chart.defaults.font.size = 12;
Chart.defaults.color = '#2d2016';
Chart.defaults.plugins.legend.labels.usePointStyle = true;
Chart.defaults.plugins.legend.labels.pointStyleWidth = 10;

// Monthly Revenue & Profit Trend
new Chart(document.getElementById('monthlyTrendChart'), {{
  type: 'line',
  data: {{
    labels: {json.dumps(monthly_labels)},
    datasets: [
      {{
        label: 'Revenue',
        data: {json.dumps(monthly_revenue)},
        borderColor: PRIMARY,
        backgroundColor: 'rgba(59,31,11,0.08)',
        fill: true,
        tension: 0.3,
        pointRadius: 3,
        pointHoverRadius: 6,
        borderWidth: 2.5
      }},
      {{
        label: 'Profit',
        data: {json.dumps(monthly_profit)},
        borderColor: ACCENT,
        backgroundColor: 'rgba(212,165,116,0.08)',
        fill: true,
        tension: 0.3,
        pointRadius: 3,
        pointHoverRadius: 6,
        borderWidth: 2.5
      }}
    ]
  }},
  options: {{
    responsive: true,
    maintainAspectRatio: false,
